#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace batch_insert_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  float price;
  std::string category;
  int stock;
};

/**
 * Function: Perform efficient batch insertion of product data using a transaction.
 * 
 * @param products List of products to insert
 * @return true if all inserts succeed, false otherwise
 */
bool batch_insert_products(const std::vector<Product>& products) {
  try {
    // Connect to the SQLite database
    auto db = sqlgen::sqlite::Connection::make("test_db.sqlite");

    // Drop the table if it exists
    db.execute("DROP TABLE IF EXISTS Product");

    // Create the Product table
    db.create_table<Product>();

    // Begin transaction
    auto transaction = db.begin_transaction();

    // Insert all products
    for (const auto& product : products) {
      db.insert(product);
    }

    // Commit the transaction
    transaction.commit();

    return true;
  } catch (...) {
    return false;
  }
}

}  // namespace batch_insert_products
