    auto db = sqlgen::sqlite::open("test_db.sqlite");

    auto query = sqlgen::select_from<Product, Sale>()
                    .cols(sqlgen::col<&Product::category>,
                          sqlgen::sum(sqlgen::col<&Sale::quantity>).as("total_qty"),
                          sqlgen::sum(sqlgen::col<&Sale::amount>).as("total_amt"))
