#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace schema_create_trigger_audit_log {


struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int stock;
};

struct AuditLog {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> log_id;
  std::string table_name;
  int record_id;
  std::string action;
  sqlgen::DateTime timestamp;
};


/**
 * Function: Create a trigger for auditing changes on Product table.
 * @return true if trigger creation succeeds, false otherwise
 */
bool create_trigger_audit_log() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) return false;
  auto conn = conn_result.value();

  // Create tables if they don't exist (helper for standalone run, though test might do it)
  create_table<Product>(conn);
  create_table<AuditLog>(conn);

  // Execute raw SQL to create the trigger
  std::string trigger_sql = R"(
    CREATE TRIGGER IF NOT EXISTS audit_product_update
    AFTER UPDATE ON Product
    BEGIN
        INSERT INTO AuditLog (table_name, record_id, action, timestamp)
        VALUES ('Product', OLD.product_id, 'UPDATE', CURRENT_TIMESTAMP);
    END;
  )";

  auto res = exec(conn, trigger_sql);

  return res.has_value();
}

}  // namespace schema_create_trigger_audit_log

test cases:
#include <gtest/gtest.h>
#include <vector>
#include <string>

#include "schema_create_trigger_audit_log.hpp"

namespace schema_create_trigger_audit_log {

/**
 * Test Case: Test audit log trigger
 * 
 * Test Scenario:
 * - Create Product and AuditLog tables
 * - Call create_trigger_audit_log
 * - Update a record in Product
 * - Verify a corresponding record appears in AuditLog
 */
TEST(sqlite, create_trigger_audit_log) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Cleanup
  auto conn = sqlite::connect("test_db.sqlite").value();
  drop<Product>(conn);
  drop<AuditLog>(conn);
  exec(conn, "DROP TRIGGER IF EXISTS audit_product_update;");

  // 1. Create tables and trigger
  bool success = create_trigger_audit_log();
  EXPECT_TRUE(success);

  // 2. Insert initial data
  Product p1{.product_id = 1, .name = "Widget", .price = 10.0, .stock = 100};
  insert(conn, std::vector{p1});

  // 3. Update the record
  auto update_query = update<Product>("price"_c.set(12.5)) | where("product_id"_c == 1);
  auto update_res = update_query(conn);
  EXPECT_TRUE(update_res.has_value());

  // 4. Verify AuditLog
  auto logs = sqlgen::read<std::vector<AuditLog>>(conn).value();

  EXPECT_EQ(logs.size(), 1);
  EXPECT_EQ(logs[0].table_name, "Product");
  EXPECT_EQ(logs[0].record_id, 1);
  EXPECT_EQ(logs[0].action, "UPDATE");
  // Timestamp verification can be loose (just check it's not empty/null if possible, but here it's a struct field so it has value)
}

}  // namespace schema_create_trigger_audit_log

