template <class ConditionType>
friend auto operator|(const Update<ValueType, SetsType, WhereType>& _u,
                      const Where<ConditionType>& _where) {
  static_assert(std::is_same_v<WhereType, Nothing>,
                "You cannot call where(...) twice (but you can apply more "
                "than one condition by combining them with && or ||).");
  return Update<ValueType, SetsType, ConditionType>{
      .sets_ = _u.sets_, .where_ = _where.condition};
}

auto operator()(const auto& _conn) const {
    return update_impl<ValueType, SetsType, WhereType>(_conn, sets_, where_);
  }

template <class ValueType, class... SetsType>
auto update(const SetsType&... _sets) {
  static_assert(sizeof...(_sets) > 0, "You must update at least one column.");
  using TupleType = rfl::Tuple<std::remove_cvref_t<SetsType>...>;
  return Update<ValueType, TupleType>{.sets_ = TupleType(_sets...)};
};

dynamic::CreateTable to_create_table(const bool _if_not_exists = true) {
  using NamedTupleType = rfl::named_tuple_t<std::remove_cvref_t<T>>;
  using Fields = typename NamedTupleType::Fields;

  static_assert(get_table_or_view<T>() == dynamic::TableOrView::table,
                "You cannot create a view using create_table(...).");

  return dynamic::CreateTable{
      .table =
          dynamic::Table{.name = get_tablename<T>(), .schema = get_schema<T>()},
      .columns = make_columns<Fields>(
          std::make_integer_sequence<int, rfl::tuple_size_v<Fields>>()),
      .if_not_exists = _if_not_exists};
}

auto operator()(const auto& _conn) const {
    return begin_transaction_impl(_conn);
  }

template <rfl::internal::StringLiteral _other_name,
          rfl::internal::StringLiteral _other_alias>
auto set(const Col<_other_name, _other_alias>& _to) const noexcept {
  return transpilation::Set<transpilation::Col<_name, _alias>,
                            transpilation::Col<_other_name, _other_alias>>{
      .to = transpilation::Col<_other_name, _other_alias>{}};
}

template <class T>
auto set(const T& _to) const noexcept {
  return transpilation::Set<transpilation::Col<_name, _alias>,
                            std::remove_cvref_t<T>>{.to = _to};
}

auto set(const char* _to) const noexcept {
    return transpilation::Set<transpilation::Col<_name, _alias>, std::string>{
        .to = _to};
  }

template <class T>
friend auto operator==(const Col&, const T& _t) {
  return transpilation::make_condition(transpilation::conditions::equal(
      transpilation::Col<_name, _alias>{},
      transpilation::to_transpilation_type(_t)));
}

