```python
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace soft_delete_records {

struct Document {
  sqlgen::PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<sqlgen::DateTime> deleted_at;
};

bool soft_delete_records(const std::vector<int>& ids) {
    if (ids.empty()) {
        return true;
    }

    auto connection = sqlgen::sqlite::connect("test_db.sqlite");
    if (!connection) {
        return false;
    }

    auto update_result = connection.value().transaction([](auto& trans) {
        for (const auto& id : ids) {
            auto result = trans.write(Document{.doc_id = id, .is_deleted = 1});
            if (!result) {
                return false;
            }
        }
        return true;
    });

    return update_result.has_value() && update_result.value();
}

}  // namespace soft_delete_records

