#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace transaction_transfer_funds {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
};

bool transfer_funds(int from_account_id, int to_account_id, double amount) {
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn) {
    return false;
  }

  auto transaction_result = conn.value()->begin_transaction();
  if (!transaction_result) {
    return false;
  }

  try {
    // Check if from_account has sufficient balance and update
    auto update_from = sqlgen::update<Account>().set(
      [](auto& a) { return std::tie(a.balance); },
      [=](const auto& a) { 
        return std::make_tuple(a.balance - amount); 
      }
    ).where([=](const auto& a) {
      return a.account_id == from_account_id && a.balance >= amount;
    });

    auto result1 = conn.value()->execute(update_from);
    if (!result1 || result1.value().count == 0) {
      conn.value()->rollback();
      return false;
    }

    // Update to_account balance
    auto update_to = sqlgen::update<Account>().set(
      [](auto& a) { return std::tie(a.balance); },
      [=](const auto& a) { 
        return std::make_tuple(a.balance + amount); 
      }
    ).where([=](const auto& a) {
      return a.account_id == to_account_id;
    });

    auto result2 = conn.value()->execute(update_to);
    if (!result2 || result2.value().count == 0) {
      conn.value()->rollback();
      return false;
    }

    conn.value()->commit();
    return true;
  } catch (...) {
    conn.value()->rollback();
    return false;
  }
}

}  // namespace transaction_transfer_funds

