```python
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace upsert_inventory_items {

struct Inventory {
  sqlgen::PrimaryKey<int> item_id;
  std::string name;
  int quantity;
};

/**
 * This function demonstrates how to use upsert (insert or replace) statements in sqlgen write API.
 * It inserts or replaces the given inventory items in the Inventory table.
 * Returns: true if the item is inserted, false if the item is already in the table.
 */
bool upsert_inventory_items(Inventory item) {
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn) {
    throw std::runtime_error("Failed to connect to database");
  }

  // Check if item exists before upsert
  auto read_query = sqlgen::read<Inventory> | sqlgen::where(&Inventory::item_id == item.item_id);
  auto existing_items = read_query(*conn);

  bool item_exists = !existing_items.empty();

  // Perform upsert operation
  auto write_query = sqlgen::write<Inventory> | sqlgen::on_conflict_replace();
  write_query(*conn, {item});

  // Return true if item was inserted (didn't exist before), false if it was replaced
  return !item_exists;
}

}  // namespace upsert_inventory_items
