      select_from<Event>(col<"event_id"> | as<"event_id">, col<"name"> | as<"name">,
                         col<"created_at"> | as<"created_at">) |
      order_by(col<"created_at">.desc()) | limit(n) | to<std::vector<Event>>;
  return query(conn).value();
}

