namespace mathematical_operations_analysis {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int quantity;
  double discount_rate;
};

struct MathAnalysis {
  int product_id;
  std::string name;
  double abs_price;
  double ceil_price;
  double floor_price;
  double rounded_price;
  double exp_discount;
  double ln_price;
  double log2_quantity;
  double sin_discount;
  double cos_discount;
  double tan_discount;
  double sqrt_quantity;
};

/**
 * Insert products into a temporary SQLite table and run a SELECT that computes
 * various mathematical expressions, returning results as std::vector<MathAnalysis>.
 */
std::vector<MathAnalysis> analyze_mathematical_operations() {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;

  auto db = connect("test_db.sqlite");

  auto select_stmt = select(
      col<&Product::product_id>,
      col<&Product::name>,
      sqlgen::abs(col<&Product::price>).as<&MathAnalysis::abs_price>(),
      sqlgen::ceil(col<&Product::price>).as<&MathAnalysis::ceil_price>(),
      sqlgen::floor(col<&Product::price>).as<&MathAnalysis::floor_price>(),
      sqlgen::round(col<&Product::price>, 2).as<&MathAnalysis::rounded_price>(),
      sqlgen::exp(col<&Product::discount_rate> / 100.0).as<&MathAnalysis::exp_discount>(),
      sqlgen::ln(col<&Product::price>).as<&MathAnalysis::ln_price>(),
      sqlgen::log2(col<&Product::quantity>).as<&MathAnalysis::log2_quantity>(),
      sqlgen::sin(col<&Product::discount_rate>).as<&MathAnalysis::sin_discount>(),
      sqlgen::cos(col<&Product::discount_rate>).as<&MathAnalysis::cos_discount>(),
      sqlgen::tan(col<&Product::discount_rate>).as<&MathAnalysis::tan_discount>(),
      sqlgen::sqrt(col<&Product::quantity>).as<&MathAnalysis::sqrt_quantity>()
  ).from<Product>();

  std::vector<MathAnalysis> result;
  for (const auto& row : db->execute(select_stmt)) {
    result.push_back(row);
  }

  return result;
}

}  // namespace mathematical_operations_analysis
