```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace trim_and_length_validation {

struct UserProfile {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
  std::string email;
};

struct ValidatedProfile {
  sqlgen::PrimaryKey<int> user_id;
  std::string trimmed_name;
  std::string trimmed_email;
  int name_length;
  int email_length;
};

/**
 * This function demonstrates how to trim whitespace from string columns and validate their lengths using sqlgen read API.
 * Returns: std::vector<ValidatedProfile>, where each struct contains the user_id, trimmed_name, trimmed_email, name_length, and email_length.
 */
std::vector<ValidatedProfile> trim_and_length_validation() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  return sqlite::connect("test_db.sqlite")
      .and_then(read<std::vector<UserProfile>>)
      .transform([](const std::vector<UserProfile>& profiles) {
        std::vector<ValidatedProfile> validated_profiles;
        validated_profiles.reserve(profiles.size());

        for (const auto& profile : profiles) {
          // Trim whitespace from name and email
          const auto trimmed_name = sqlgen::internal::strings::trim(profile.name);
          const auto trimmed_email = sqlgen::internal::strings::trim(profile.email);

          // Calculate lengths
          const auto name_length = static_cast<int>(trimmed_name.length());
          const auto email_length = static_cast<int>(trimmed_email.length());

          validated_profiles.push_back(ValidatedProfile{
              .user_id = profile.user_id,
              .trimmed_name = trimmed_name,
              .trimmed_email = trimmed_email,
              .name_length = name_length,
              .email_length = email_length
          });
        }

        return validated_profiles;
      })
      .value();
}

}  // namespace trim_and_length_validation
