struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by querying the OrderItem table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl() {
  const auto db_path = "test_db.sqlite";
  const auto connection = sqlgen::sqlite::connect(db_path);

  if (!connection) {
    throw std::runtime_error("Failed to connect to database");
  }

  const auto query = 
    sqlgen::select_from<OrderItem>(
      "item_id"_c,
      "order_id"_c,
      "product_id"_c,
      "unit_price"_c,
      "quantity"_c,
      sqlgen::coalesce("discount_rate"_c, 0.0).as<"discount_rate">(),
      sqlgen::coalesce("tax_rate"_c, 0.0).as<"tax_rate">(),
      ("unit_price"_c * "quantity"_c).as<"gross_total">(),
      ("unit_price"_c * "quantity"_c * (1.0 - sqlgen::coalesce("discount_rate"_c, 0.0) / 100.0)).as<"discounted_total">(),
      ("unit_price"_c * "quantity"_c * (1.0 - sqlgen::coalesce("discount_rate"_c, 0.0) / 100.0) * (1.0 + sqlgen::coalesce("tax_rate"_c, 0.0) / 100.0)).as<"final_total">(),
      ("unit_price"_c * "quantity"_c / "quantity"_c).as<"unit_cost">(),
      ("quantity"_c % 10).as<"quantity_group">(),
      ("unit_price"_c * 0.3).as<"estimated_profit">()
    );

  const auto result = connection.value().read(query);

  if (!result) {
    throw std::runtime_error("Failed to execute query");
  }

  std::vector<OrderMetrics> metrics;
  for (const auto& row : *result) {
    metrics.push_back(OrderMetrics{
      .item_id = row.item_id,
      .order_id = row.order_id,
      .product_id = row.product_id,
