#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace replace_text_in_notes {

struct Note {
  sqlgen::PrimaryKey<int> note_id;
  std::string content;
};

struct UpdatedNote {
  sqlgen::PrimaryKey<int> note_id;
  std::string updated_content;
};

/**
 * description: replace_text_in_notes.
 * This function demonstrates how to replace text in notes using sqlgen update API.
 * It replaces all occurrences of "foo" with "bar" in the content column of the Note table.
 * Returns: std::vector<UpdatedNote>.
 */
std::vector<UpdatedNote> replace_text_in_notes() {
  auto conn = sqlgen::sqlite::Connection::make("test_db.sqlite").value();

  // First, we need to select all notes to process them
  auto select_query = sqlgen::select<Note>();
  auto notes = sqlgen::execute(select_query, conn).value();

  std::vector<UpdatedNote> result;

  // Process each note
  for (const auto& note : notes) {
    std::string updated_content = note.content;

    // Replace all occurrences of "foo" with "bar"
    size_t pos = 0;
    while ((pos = updated_content.find("foo", pos)) != std::string::npos) {
      updated_content.replace(pos, 3, "bar");
      pos += 3;
    }

    // Update the record in the database
    auto update_query = sqlgen::update<Note>().set<Note::content>(updated_content)
                         .where<Note::note_id>(note.note_id.value());
    sqlgen::execute(update_query, conn).value();

    // Add to result
    result.push_back({note.note_id, updated_content});
  }

  return result;
}

}  // namespace replace_text_in_notes
