```python
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace inventory_bulk_write_and_read {

struct Inventory {
  sqlgen::PrimaryKey<int> item_id;
  std::string name;
  int quantity;
  std::string location;
};

/**
 * description: inventory_bulk_write_and_read.
 * This function demonstrates how to perform bulk write and read operations on an inventory table.
 * It first drops and recreates the table, then writes the given items to the table.
 * Finally, it reads back the items with quantity > 50, orders them by quantity in descending order,
 * and returns true if at least one item is found.
 * Returns: bool.
 */
bool inventory_bulk_write_and_read(const std::vector<Inventory>& items) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  auto conn = sqlite::Connection::make("test_db.sqlite");
  if (!conn) {
    return false;
  }

  // Drop and recreate the table
  const auto drop_query = sqlgen::drop_table<Inventory> | if_exists;
  const auto create_query = sqlgen::create_table<Inventory> | if_not_exists;

  if (auto res = (*conn)->execute(drop_query); !res) {
    return false;
  }

  if (auto res = (*conn)->execute(create_query); !res) {
    return false;
  }

  // Begin transaction for bulk insert
  if (auto res = (*conn)->begin_transaction(); !res) {
    return false;
  }

  // Write the items
  const auto write_query = sqlgen::write<Inventory>;
  for (const auto& item : items) {
    if (auto res = (*conn)->execute(write_query, item); !res) {
      return false;
    }
  }

  // Commit transaction
  if (auto res = (*conn)->commit(); !res) {
    return false;
  }

  // Read items with quantity > 50 ordered by quantity descending
  const auto read_query = sqlgen::read<std::vector<Inventory>> | 
                         where("quantity"_c > 50) | 
                         order_by("quantity"_c.desc());

  const auto result = (*conn)->execute(read_query);
  if (!result) {
    return false;
  }

  // Check if at least one item was found
  return !result.value().empty();
}

}  // namespace inventory_bulk_write_and_read
