output.text:
```python
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace cascade_delete_demo {

struct Parent {
  sqlgen::PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  sqlgen::PrimaryKey<int> child_id;
  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * @param parent_id The ID of the parent record to delete.
 * Returns: true if the cascade delete worked as expected, false otherwise.
 */
bool cascade_delete_demo(int parent_id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto connection = sqlite::connect("test_db.sqlite")
                    .and_then(exec("PRAGMA foreign_keys = ON"))
                    .and_then(drop<Child> | if_exists)
                    .and_then(drop<Parent> | if_exists)
                    .and_then(create_table<Parent>)
                    .and_then(create_table<Child>)
                    .value();

  // Insert parent record
  Parent parent_record{.parent_id = parent_id, .name = "Parent Name"};
  connection = connection.and_then(insert(parent_record)).value();

  // Insert child records
  Child child1{.child_id = 1, .parent_id = parent_id, .note = "Child 1"};
  Child child2{.child_id = 2, .parent_id = parent_id, .note = "Child 2"};
  connection = connection.and_then(insert(child1)).and_then(insert(child2)).value();

  // Verify child records were inserted
  auto child_count_before = connection.and_then(count<Child>()).value()._result;
  if (child_count_before != 2) {
    return false;
  }

  // Delete parent record
  connection = connection.and_then(remove<Parent>(where(Parent::parent_id == parent_id))).value();

  // Check if child records were automatically deleted
  auto child_count_after = connection.and_then(count<Child>()).value()._result;

  // Return true if all child records were deleted (cascade delete worked)
  return child_count_after == 0;
}

}  // namespace cascade_delete_demo
```

