#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace update_set_operations {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * sets the balance and status of an Account identified by acc_id.
 * @param acc_id: The id of Account to be updated.
 * @returns true if the update operations are successful, and false otherwise.
 */
bool update_set_operations(int acc_id) {
  try {
    // Connect to the SQLite database
    auto conn = sqlgen::sqlite::Connection::make("test_db.sqlite").value();

    // Begin transaction
    conn->begin_transaction().value();

    // Create Account table if it doesn't exist
    sqlgen::create_table_if_not_exists<Account>(conn).value();

    // Update balance and status using set(...)
    sqlgen::update<Account>(conn)
        .set(sqlgen::set(&Account::balance, 1500.75),
             sqlgen::set(&Account::status, "active"))
        .where(sqlgen::where(&Account::account_id, acc_id))
        .value();

    // Commit transaction
    conn->commit().value();

    // Verify changes persisted by reading the updated record
    auto result = sqlgen::select_from<Account>(conn)
                     .where(sqlgen::where(&Account::account_id, acc_id))
                     .execute()
                     .value();

    if (result.empty()) {
      return false;
    }

    const auto& account = result.front();
    return (account.balance == 1500.75 && account.status == "active");

  } catch (...) {
    return false;
  }
}

}  // namespace update_set_operations
