#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace analyze_department_employees {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string department_name;
  std::string location;
};

struct Employee {
  sqlgen::PrimaryKey<int> employee_id;
  int department_id;
  std::string first_name;
  std::string last_name;
  double salary;
};

struct JoinResult {
  std::optional<std::string> department_name;
  std::optional<std::string> first_name;
  std::optional<std::string> last_name;
  std::optional<double> salary;
};

struct JoinAnalysis {
  std::vector<JoinResult> inner_join_results;
  std::vector<JoinResult> left_join_results;
  std::vector<JoinResult> right_join_results;
  std::vector<JoinResult> full_join_results;
};

/**
 * analyze_department_employees
 * Provides data-join analysis between Department and Employee input collections by
 * creating temporary SQL tables, inserting the provided rows, and executing a
 * variety of join queries to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees() {
  // Create database connection
  auto db = sqlgen::sqlite::connect("test_db.sqlite");

  // Create tables
  db.create_table<Department>();
  db.create_table<Employee>();

  // Clear existing data
  db.remove_all<Department>();
  db.remove_all<Employee>();

  // Insert sample data into Department table
  std::vector<Department> departments = {
    Department{.department_id = 1, .department_name = "Engineering", .location = "Building A"},
    Department{.department_id = 2, .department_name = "Marketing", .location = "Building B"},
    Department{.department_id = 3, .department_name = "Sales", .location = "Building C"},
    Department{.department_id = 4, .department_name = "HR", .location = "Building D"}
  };

  // Insert sample data into Employee table
  std::vector<Employee> employees = {
    Employee{.employee_id = 1, .department_id = 1, .first_name = "John", .last_name = "Doe", .salary = 75000.0},
    Employee{.employee_id = 2, .department_id = 1, .first_name = "Jane", .last_name = "Smith", .salary = 80000.0},
    Employee{.employee_id = 3, .department_id = 2, .first_name = "Mike", .last_name = "Johnson", .salary = 65000.0},
    Employee{.employee_id = 4, .department_id = 3, .first_name = "Sarah", .last_name = "Williams", .salary = 70000.0},
    Employee{.employee_id = 5, .department_id = 0, .first_name = "David", .last_name = "Brown", .salary = 60000.0}, // No department
    Employee{.employee_id = 6, .department_id = 5, .first_name = "Lisa", .last_name = "Davis", .salary = 68000.0}  // Non-existent department
  };

  for (const auto& dept : departments) {
    db.insert(dept);
  }

  for (const auto& emp : employees) {
    db.insert(emp);
  }

  JoinAnalysis analysis;

  // 1. INNER JOIN - Get employees with assigned departments
  auto inner_join_query = db.from<Department>()
    .inner_join<Employee>(sqlgen::on(
      &Department::department_id, &Employee::department_id))
    .select<
      decltype(&Department::department_name),
      decltype(&Employee::first_name),
      decltype(&Employee::last_name),
      decltype(&Employee::salary)>();

  for (const auto& row : inner_join_query.execute()) {
    analysis.inner_join_results.push_back(JoinResult{
      .department_name = std::get<0>(row),
      .first_name = std::get<1>(row),
      .last_name = std::get<2>(row),
      .salary = std::get<3>(row)
    });
  }

  // 2. LEFT JOIN - Include all employees (even without departments)
  auto left_join_query = db.from<Employee>()
    .left_join<Department>(sqlgen::on(
      &Employee::department_id, &Department::department_id))
    .select<
      decltype(&Department::department_name),
      decltype(&Employee::first_name),
      decltype(&Employee::last_name),
      decltype(&Employee::salary)>();

  for (const auto& row : left_join_query.execute()) {
    analysis.left_join_results.push_back(JoinResult{
      .department_name = std::get<0>(row),
      .first_name = std::get<1>(row),
      .last_name = std::get<2>(row),
      .salary = std::get<3>(row)
    });
  }

  // 3. RIGHT JOIN - Include all departments (even without employees)
  auto right_join_query = db.from<Employee>()
    .right_join<Department>(sqlgen::on(
      &Employee::department_id, &Department::department_id))
    .select<
      decltype(&Department::department_name),
      decltype(&Employee::first_name),
      decltype(&Employee::last_name),
      decltype(&Employee::salary)>();

  for (const auto& row : right_join_query.execute()) {
    analysis.right_join_results.push_back(JoinResult{
      .department_name = std::get<0>(row),
      .first_name = std::get<1>(row),
      .last_name = std::get<2>(row),
      .salary = std::get<3>(row)
    });
  }

  // 4. FULL JOIN - Include all employees and departments
  auto full_join_query = db.from<Employee>()
    .full_join<Department>(sqlgen::on(
      &Employee::department_id, &Department::department_id))
    .select<
      decltype(&Department::department_name),
      decltype(&Employee::first_name),
      decltype(&Employee::last_name),
      decltype(&Employee::salary)>();

  for (const auto& row : full_join_query.execute()) {
    analysis.full_join_results.push_back(JoinResult{
      .department_name = std::get<0>(row),
      .first_name = std::get<1>(row),
      .last_name = std::get<2>(row),
      .salary = std::get<3>(row)
    });
  }

  return analysis;
}

}  // namespace analyze_department_employees
