#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace create_view_order_summary {

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  std::string customer;
};

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  double unit_price;
  int quantity;
};

struct OrderSummary {
  static constexpr const char* tablename = "OrderSummaryView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string customer;
  double total;
};

/**
 * Description: Create a view `OrderSummaryView` that shows order ID, customer name, and (unit_price * quantity) as total price for each order.
 * Returns: std::vector<OrderSummary>.
 */
std::vector<OrderSummary> create_view_order_summary() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to the SQLite database
    auto connection = sqlite::connect("test_db.sqlite");
    if (!connection) {
        throw std::runtime_error("Failed to connect to database");
    }

    // Define the query to create the view
    auto order_summary_query = select_from<Order, OrderItem>(
        "order_id"_c,
        "customer"_c,
        sum("unit_price"_c * "quantity"_c).as("total")
    ).where("Order.order_id"_c == "OrderItem.order_id"_c)
     .group_by("order_id"_c, "customer"_c);

    // Create the CREATE VIEW statement
    auto create_view_stmt = create_as<OrderSummary>(order_summary_query) | if_not_exists;

    // Execute the CREATE VIEW statement
    auto result = connection.value().execute(create_view_stmt);
    if (!result) {
        throw std::runtime_error("Failed to create view");
    }

    // Query the view
    auto select_stmt = select_from<OrderSummary>("order_id"_c, "customer"_c, "total"_c);
    auto records = connection.value().execute(select_stmt);

    if (!records) {
        throw std::runtime_error("Failed to select from view");
    }

    return records.value();
}

}  // namespace create_view_order_summary
