std::vector<WeekdayStats> weekday_sales_analysis() {
  auto db = sqlgen::sqlite::connect("test_db.sqlite");

  auto query = sqlgen::select_from<Sales>()
                 .columns(sqlgen::col<&Sales::sale_date>(), 
                          sqlgen::sum(sqlgen::col<&Sales::quantity>()))
                 .group_by(sqlgen::strftime("%w", sqlgen::col<&Sales::sale_date>()));

  std::vector<WeekdayStats> result;

  for (const auto& row : db.execute(query)) {
    result.push_back(WeekdayStats{std::get<0>(row), std::get<1>(row)});
  }

  return result;
}

}  // namespace weekday_sales_analysis
