```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace group_by_with_aggregations {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
};

struct Post {
  sqlgen::PrimaryKey<int> post_id;
  int user_id;
  std::string content;
};

struct Stats {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
  int post_count;
  std::optional<double> avg_length;
};

/**
 * Description: This function retrieves user statistics including post count and average post length.
 * Returns: std::vector<Stats>.
 */
std::vector<Stats> group_by_with_aggregations() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  const auto query = 
    select_from<User, Post>(
      "user_id"_c.as<"user_id">(),
      "name"_c.as<"name">(),
      count("post_id"_c).as<"post_count">(),
      avg(length("content"_c)).as<"avg_length">()
    ) 
    | join_on<"user_id"_c>
    | group_by<"user_id"_c, "name"_c>
    | to<Stats>;

  return sqlite::connect("test_db.sqlite")
    .and_then(query)
    .value();
}

}  // namespace group_by_with_aggregations
