#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace create_table_as_select {

struct Source {
  sqlgen::PrimaryKey<int> id;
  int value;
};

struct Target {
  int value;
};

/**
 * Description: This function creates a table `Target` from a select query on `Source` 
 * Returns: std::vector<Target>.
 */
inline std::vector<Target> create_table_as_select() {
    // Connect to the SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite").value();

    // Construct the CREATE TABLE AS SELECT statement
    const auto create_as_stmt = 
        sqlgen::create_as<Target>(
            sqlgen::select_from<Source>()
                .where([](const auto& source) { return source.value > 100; })
        );

    // Execute the statement to create the table
    conn->execute(create_as_stmt).value();

    // Now select all records from the newly created Target table
    const auto select_stmt = sqlgen::select_from<Target>();
    return conn->execute(select_stmt).value();
}

}  // namespace create_table_as_select
